class SimpleHashMap<K,V> {
    static class Node<K,V> { K key; V val; int hash; Node<K,V> next; }

    Node<K,V>[] table = new Node[16];
    int size; float loadFactor = 0.75f;

    int hash(K k){ int h = k.hashCode(); return h ^ (h>>>16); }
    int index(int h){ return h & (table.length-1); }   // bitwise AND

    void put(K k, V v){
        int h = hash(k), i = index(h);
        for (Node<K,V> n = table[i]; n != null; n = n.next)
            if (n.hash==h && n.key.equals(k)) { n.val=v; return; }
        table[i] = new Node<>(k,v,h,table[i]);          // prepend
        if (++size > table.length*loadFactor) resize();
    }
    V get(K k){
        int h = hash(k);
        for (Node<K,V> n=table[index(h)]; n!=null; n=n.next)
            if (n.hash==h && n.key.equals(k)) return n.val;
        return null;
    }
    void resize(){ /* double capacity, rehash every node */ }
}
